initJs:
function(container, apiUrl, tables) {
  let stores = [];
  let categories = [];
  let isProcessing = false;

  // 初期化処理
  async function initialize() {
    try {
      // 店舗データを取得
      const storeData = await window.aivicApi.list(1); // 店舗マスタ
      stores = storeData || [];

      // 商品データから商品カテゴリを取得
      const productData = await window.aivicApi.list(2); // 商品マスタ
      const categoryIds = [...new Set((productData || []).map(p => p.商品カテゴリID).filter(Boolean))];
      categories = categoryIds.map(id => ({ id, name: `カテゴリ${id.slice(-4)}` }));

      renderStoreOptions();
      renderCategoryCheckboxes();
      setDefaultDates();
    } catch (error) {
      console.error('初期化エラー:', error);
    }
  }

  // 店舗選択肢を描画
  function renderStoreOptions() {
    const storeSelect = container.querySelector('#store-select');
    storeSelect.innerHTML = '<option value="">店舗を選択してください</option>';

    stores.forEach(store => {
      const option = document.createElement('option');
      option.value = store.店舗ID;
      option.textContent = `${store.店舗コード} - ${store.店舗名}`;
      storeSelect.appendChild(option);
    });
  }

  // 商品カテゴリチェックボックスを描画
  function renderCategoryCheckboxes() {
    const categoryContainer = container.querySelector('#category-checkboxes');
    categoryContainer.innerHTML = '';

    categories.forEach(category => {
      const label = document.createElement('label');
      label.innerHTML = `
        <input type="checkbox" value="${category.id}" class="category-checkbox">
        ${category.name}
      `;
      categoryContainer.appendChild(label);
    });
  }

  // デフォルト日付を設定
  function setDefaultDates() {
    const today = new Date();
    const tomorrow = new Date(today);
    tomorrow.setDate(tomorrow.getDate() + 1);
    const nextWeek = new Date(today);
    nextWeek.setDate(nextWeek.getDate() + 7);
    const lastYear = new Date(today);
    lastYear.setFullYear(lastYear.getFullYear() - 1);

    container.querySelector('#prediction-start-date').value = tomorrow.toISOString().split('T')[0];
    container.querySelector('#prediction-end-date').value = nextWeek.toISOString().split('T')[0];
    container.querySelector('#learning-start-date').value = lastYear.toISOString().split('T')[0];
    container.querySelector('#learning-end-date').value = today.toISOString().split('T')[0];
  }

  // バリデーション
  function validateInputs() {
    const errors = [];

    // 予測対象期間チェック
    const startDate = new Date(container.querySelector('#prediction-start-date').value);
    const endDate = new Date(container.querySelector('#prediction-end-date').value);
    const today = new Date();
    today.setHours(0, 0, 0, 0);

    if (startDate <= today) {
      errors.push('予測対象期間に過去の日付は選択できません');
    }
    if (endDate <= startDate) {
      errors.push('終了日は開始日より後の日付を選択してください');
    }

    // 店舗選択チェック
    if (!container.querySelector('#store-select').value) {
      errors.push('店舗を選択してください');
    }

    // 商品カテゴリ選択チェック
    const selectedCategories = container.querySelectorAll('.category-checkbox:checked');
    if (selectedCategories.length === 0) {
      errors.push('商品カテゴリを選択してください');
    }

    // 予測モデル選択チェック
    const selectedModel = container.querySelector('input[name="prediction-model"]:checked');
    if (!selectedModel) {
      errors.push('予測モデルを選択してください');
    }

    // 学習データ期間チェック
    const learningStart = container.querySelector('#learning-start-date').value;
    const learningEnd = container.querySelector('#learning-end-date').value;
    if (!learningStart || !learningEnd) {
      errors.push('学習データ期間を設定してください');
    }

    // 予測精度閾値チェック
    const threshold = parseInt(container.querySelector('#accuracy-threshold').value);
    if (isNaN(threshold) || threshold < 0 || threshold > 100) {
      errors.push('予測精度閾値は0-100の範囲で入力してください');
    }

    return errors;
  }

  // エラーメッセージ表示
  function showErrors(errors) {
    const errorContainer = container.querySelector('#error-messages');
    if (errors.length > 0) {
      errorContainer.innerHTML = errors.map(error => `<div>• ${error}</div>`).join('');
      errorContainer.classList.remove('hidden');
    } else {
      errorContainer.classList.add('hidden');
    }
  }

  // 進捗バー更新
  function updateProgress(percentage, text = '処理中...') {
    const progressFill = container.querySelector('#progress-fill');
    const progressText = container.querySelector('#progress-text');
    progressFill.style.width = `${percentage}%`;
    progressText.textContent = text;
  }

  // 予測結果を描画
  function renderPredictionResults(results) {
    const tbody = container.querySelector('#results-tbody');
    tbody.innerHTML = results.map(result => `
      <tr data-id="${result.予測結果ID}">
        <td>${new Date(result.予測対象日).toLocaleDateString()}</td>
        <td>${result.商品名 || 'N/A'}</td>
        <td>${result.予測数量}</td>
        <td>${result.予測精度}%</td>
        <td>${result.推奨発注数量}</td>
        <td>
          <button class="action-btn secondary" onclick="window.showScreen('scr-1778591852463')">発注管理へ</button>
        </td>
      </tr>
    `).join('');

    container.querySelector('#prediction-results').classList.remove('hidden');
  }

  // AI予測実行
  async function executePrediction() {
    if (isProcessing) return;

    const errors = validateInputs();
    showErrors(errors);
    if (errors.length > 0) return;

    isProcessing = true;
    const executeBtn = container.querySelector('#btn-execute-prediction');
    const progressContainer = container.querySelector('#progress-container');

    executeBtn.disabled = true;
    executeBtn.textContent = '処理中...';
    progressContainer.classList.remove('hidden');

    try {
      // 進捗シミュレーション
      updateProgress(10, 'データ準備中...');
      await new Promise(resolve => setTimeout(resolve, 500));

      updateProgress(30, '学習データ分析中...');
      await new Promise(resolve => setTimeout(resolve, 1000));

      updateProgress(60, 'AI予測実行中...');
      await new Promise(resolve => setTimeout(resolve, 1500));

      updateProgress(90, '結果生成中...');
      await new Promise(resolve => setTimeout(resolve, 500));

      // 予測結果データを生成・保存
      const selectedCategories = Array.from(container.querySelectorAll('.category-checkbox:checked')).map(cb => cb.value);
      const storeId = container.querySelector('#store-select').value;
      const startDate = container.querySelector('#prediction-start-date').value;
      const endDate = container.querySelector('#prediction-end-date').value;
      const model = container.querySelector('input[name="prediction-model"]:checked').value;
      const threshold = parseInt(container.querySelector('#accuracy-threshold').value);

      const mockResults = [];
      const start = new Date(startDate);
      const end = new Date(endDate);

      for (let d = new Date(start); d <= end; d.setDate(d.getDate() + 1)) {
        selectedCategories.forEach(categoryId => {
          const accuracy = Math.max(threshold, Math.floor(Math.random() * 20) + 75);
          const quantity = Math.floor(Math.random() * 100) + 20;

          const result = {
            店舗ID: storeId,
            商品ID: `prod-${categoryId}`,
            予測対象日: new Date(d).toISOString(),
            予測数量: quantity,
            予測精度: accuracy,
            推奨発注数量: Math.ceil(quantity * 1.1),
            予測モデルバージョン: `${model}-v1.0`,
            予測ステータス: '完了',
            発注済フラグ: false,
            作成日時: new Date().toISOString(),
            更新日時: new Date().toISOString(),
            商品名: `商品${categoryId.slice(-4)}`
          };

          mockResults.push(result);
        });
      }

      // 結果をデータベースに保存
      for (const result of mockResults) {
        await window.aivicApi.save(9, result); // 需要予測結果テーブル
      }

      updateProgress(100, '完了');
      renderPredictionResults(mockResults);

    } catch (error) {
      console.error('予測実行エラー:', error);
      showErrors(['予測処理中にエラーが発生しました']);
    } finally {
      isProcessing = false;
      executeBtn.disabled = false;
      executeBtn.textContent = 'AI予測実行';
      setTimeout(() => {
        progressContainer.classList.add('hidden');
        updateProgress(0);
      }, 2000);
    }
  }

  // 天候データ取込
  async function importWeatherData() {
    const statusSpan = container.querySelector('#weather-status');
    statusSpan.textContent = '取込中...';

    try {
      // 模擬的な天候データ取込
      await new Promise(resolve => setTimeout(resolve, 1000));

      const mockWeatherData = {
        店舗ID: container.querySelector('#store-select').value || stores[0]?.店舗ID,
        観測日: new Date().toISOString(),
        天気: '晴れ',
        最高気温: 25,
        最低気温: 18,
        平均気温: 22,
        降水量: 0,
        湿度: 60,
        風速: 3,
        データ種別: '実績値',
        データソース: '気象庁API',
        作成日時: new Date().toISOString(),
        更新日時: new Date().toISOString()
      };

      await window.aivicApi.save(4, mockWeatherData); // 天候データテーブル
      statusSpan.textContent = '取込完了';
      statusSpan.style.color = '#28a745';
    } catch (error) {
      console.error('天候データ取込エラー:', error);
      statusSpan.textContent = '取込失敗';
      statusSpan.style.color = '#dc3545';
      showErrors(['天候データの取込に失敗しました']);
    }
  }

  // イベントデータ取込
  async function importEventData() {
    const statusSpan = container.querySelector('#events-status');
    statusSpan.textContent = '取込中...';

    try {
      // 模擬的なイベントデータ取込
      await new Promise(resolve => setTimeout(resolve, 800));

      const mockEventData = {
        店舗ID: container.querySelector('#store-select').value || stores[0]?.店舗ID,
        イベント名: 'サンプルイベント',
        イベント種別: 'セール',
        開始日時: new Date().toISOString(),
        終了日時: new Date(Date.now() + 86400000).toISOString(),
        予想来場者数: 500,
        影響度: '中',
        場所: '店舗周辺',
        店舗からの距離: 100,
        有効フラグ: true,
        作成日時: new Date().toISOString(),
        更新日時: new Date().toISOString(),
        作成者: 'システム',
        更新者: 'システム'
      };

      await window.aivicApi.save(5, mockEventData); // イベントデータテーブル
      statusSpan.textContent = '取込完了';
      statusSpan.style.color = '#28a745';
    } catch (error) {
      console.error('イベントデータ取込エラー:', error);
      statusSpan.textContent = '取込失敗';
      statusSpan.style.color = '#dc3545';
      showErrors(['イベントデータの取込に失敗しました']);
    }
  }

  // イベントリスナー設定
  container.querySelector('#btn-execute-prediction').addEventListener('click', executePrediction);
  container.querySelector('#btn-import-weather').addEventListener('click', importWeatherData);
  container.querySelector('#btn-import-events').addEventListener('click', importEventData);

  // 季節要因スライダー
  const seasonalSlider = container.querySelector('#seasonal-factor');
  const seasonalValue = container.querySelector('#seasonal-value');
  seasonalSlider.addEventListener('input', (e) => {
    seasonalValue.textContent = e.target.value;
  });

  // 初期化実行
  initialize();
}
